<template><article class="card repair-card" :class="{'repair-overdue':repair.overdue}"><div class="repair-main"><div class="repair-head"><h3>{{repair.title}}</h3><el-tag :type="priorityKind" effect="dark" size="small">{{repairPriorityText[repair.priority]}}</el-tag><el-tag v-if="repair.overdue" type="danger" effect="dark" size="small">超时</el-tag></div><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · 提交 {{new Date(repair.created_at).toLocaleString()}}</small><div class="repair-sla"><small>等级：<b>{{repairPriorityText[repair.priority]}}</b>（{{repairPriorityDeadlineText[repair.priority]}}）</small><small>截止响应：{{repair.response_due_at?new Date(repair.response_due_at).toLocaleString():'-'}}</small><small v-if="repair.response_at">首次响应：{{new Date(repair.response_at).toLocaleString()}} · 耗时 <b :class="{'sla-late':repair.overdue}">{{formatDuration(repair.response_duration)}}</b></small><small v-else class="sla-pending">尚未首次接单</small><small v-if="repair.handler">处理人：{{repair.handler.nickname}}</small></div></div><div class="repair-side"><RepairStatusBadge :status="repair.status"/><template v-if="canManage"><el-select v-if="!repair.handler_id && !final" :model-value="''" size="small" placeholder="选择处理人接单" @change="accept"><el-option v-for="s in staff" :key="s.id" :label="s.nickname" :value="s.id"/></el-select><el-select v-else-if="!final" :model-value="repair.status" size="small" @change="advance"><el-option v-for="(t,k) in advanceOptions" :key="k" :label="t" :value="k"/></el-select><small v-if="final" class="sla-done">工单已结束，记录锁定</small></template></div></article></template><script setup lang="ts">import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{assignRepair,updateRepairStatus}from'../../api/repair';import{getStaff}from'../../api/user';import{repairPriorityText,repairPriorityDeadlineText,repairStatusText,formatDuration}from'../../constants/repair';import{usePermission}from'../../hooks/usePermission';import type{Repair,RepairStatus,User}from'../../types';import RepairStatusBadge from'./RepairStatusBadge.vue';const props=defineProps<{repair:Repair}>();const emit=defineEmits<{changed:[]}>();const canManage=usePermission('repair:manage');const staff=ref<User[]>([]);const final=computed(()=>props.repair.status==='done'||props.repair.status==='closed');const priorityKind=computed(()=>({normal:'success',urgent:'warning',major:'danger'}[props.repair.priority] as 'success'|'warning'|'danger'));const advanceOptions=computed<Partial<Record<RepairStatus,string>>>(()=>{if(props.repair.status==='pending')return{assigned:repairStatusText.assigned,processing:repairStatusText.processing};if(props.repair.status==='assigned')return{processing:repairStatusText.processing,done:repairStatusText.done};if(props.repair.status==='processing')return{done:repairStatusText.done,closed:repairStatusText.closed};return{}});async function accept(handlerId:number){try{await assignRepair(props.repair.id,handlerId);ElMessage.success('已接单，首次响应时间已记录');emit('changed')}catch(e){ElMessage.error((e as Error).message)}}async function advance(status:string){try{await updateRepairStatus(props.repair.id,status as RepairStatus);ElMessage.success('工单进度已更新');emit('changed')}catch(e){ElMessage.error((e as Error).message)}}onMounted(()=>{if(canManage.value)getStaff().then(v=>{staff.value=v}).catch(()=>{})})</script>
